DROP TABLE IF EXISTS `director_proposal_votes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `director_proposal_votes` (
  `match_id` int(10) unsigned NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `option_id` int(10) unsigned NOT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`match_id`,`user_id`),
  KEY `idx_director_option` (`option_id`),
  KEY `user_id` (`user_id`),
  CONSTRAINT `director_proposal_votes_ibfk_1` FOREIGN KEY (`match_id`) REFERENCES `matches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `director_proposal_votes_ibfk_2` FOREIGN KEY (`user_id`) REFERENCES `site_users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `director_proposal_votes_ibfk_3` FOREIGN KEY (`option_id`) REFERENCES `match_draw_options` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
